#!/usr/bin/env python3
"""Test SDK receipt admission and corruption refusal with generated bytes."""
import json
from pathlib import Path
from tempfile import TemporaryDirectory
import unittest

from build import sha
import sdk_release as release

COMMIT = 'a' * 40


class BundleTest(unittest.TestCase):
    def setUp(self):
        fixture = TemporaryDirectory()
        self.addCleanup(fixture.cleanup)
        self.bundle = Path(fixture.name)
        archive = self.bundle / release.ARCHIVE
        archive.write_bytes(b'generated archive fixture; never execute it')
        self.archive_hash = sha(archive)
        config = self.bundle / release.CONFIG
        config.write_text('\n'.join(sorted(release.REQUIRED_CONFIG)) + '\n')
        test = self.bundle / release.REPORT
        test.write_text(json.dumps({
            'passed': True, 'sdk_sha256': self.archive_hash, 'sysroot_is_relocated': True,
            'elf': {'fp_abi': 6, 'stack_flags': 6, 'interpreter': '/lib/ld-linux-mipsn8.so.1'},
            'platform_touchscreen_symbols': ['q2_touchscreen_open', 'q2_touchscreen_state'],
        }))
        self.record = dict(release.identity(COMMIT), container_image='sha256:' + 'a' * 64,
                           archive_bytes=archive.stat().st_size, archive_sha256=self.archive_hash,
                           configuration_sha256=sha(config), qualification_sha256=sha(test))
        self.write_manifest()

    def write_manifest(self):
        (self.bundle / release.MANIFEST).write_text(json.dumps(self.record))
        (self.bundle / 'SHA256SUMS').write_text(release.checksum_text(self.bundle))

    def test_exact_bundle_and_expected_digest(self):
        self.assertEqual(release.verify(self.bundle, COMMIT, self.archive_hash), self.record)
        with self.assertRaisesRegex(ValueError, 'bytes differ'):
            release.verify(self.bundle, COMMIT, 'b' * 64)

    def test_wrong_source_and_changed_archive(self):
        with self.assertRaisesRegex(ValueError, 'os_commit differs'):
            release.verify(self.bundle, 'b' * 40)
        (self.bundle / release.ARCHIVE).write_bytes(b'corrupt')
        with self.assertRaisesRegex(ValueError, 'bytes differ'):
            release.verify(self.bundle, COMMIT)

    def test_configuration_and_abi_survive_checksum_rewrite(self):
        test = self.bundle / release.REPORT
        original = test.read_text()
        receipt = json.loads(original)
        receipt['elf']['fp_abi'] = 0
        test.write_text(json.dumps(receipt))
        self.record['qualification_sha256'] = sha(test)
        self.write_manifest()
        with self.assertRaisesRegex(ValueError, 'MIPS SDK qualification'):
            release.verify(self.bundle, COMMIT)
        test.write_text(original)
        config = self.bundle / release.CONFIG
        config.write_text('BR2_mipsel=y\n')
        self.record['qualification_sha256'] = sha(test)
        self.record['configuration_sha256'] = sha(config)
        self.write_manifest()
        with self.assertRaisesRegex(ValueError, 'Q2 configuration'):
            release.verify(self.bundle, COMMIT)


if __name__ == '__main__':
    unittest.main()
